const status=document.getElementById('offline-status'),button=document.getElementById('offline-save');
function message(worker,type,timeout=4000){return new Promise(resolve=>{if(!worker){resolve(false);return;}const ch=new MessageChannel();const timer=setTimeout(()=>{ch.port1.close();resolve(false);},timeout);ch.port1.onmessage=e=>{clearTimeout(timer);ch.port1.close();resolve(e.data.ready===true);};worker.postMessage(type,[ch.port2]);});}
async function refresh(){if(!('serviceWorker'in navigator)){status.textContent='Use localhost or HTTPS for offline download';button.disabled=true;return;}try{const reg=await navigator.serviceWorker.getRegistration();if(reg&&await message(reg.active,'STATUS')){status.textContent=navigator.onLine?'Offline pack ready':'Offline - ready to train';button.textContent='Refresh offline pack';}else status.textContent=navigator.onLine?'Offline pack not downloaded':'Offline pack unavailable';}catch{status.textContent='Offline storage unavailable in this browser';}}
function activated(reg){const worker=reg.installing||reg.waiting||reg.active;if(!worker)return Promise.reject(new Error('No worker'));if(worker.state==='activated')return Promise.resolve();return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{worker.removeEventListener('statechange',changed);reject(new Error('timeout'));},90000);function changed(){if(worker.state==='activated'||worker.state==='redundant'){clearTimeout(timer);worker.removeEventListener('statechange',changed);worker.state==='activated'?resolve():reject(new Error('Download failed'));}}worker.addEventListener('statechange',changed);changed();});}
button.onclick=async()=>{button.disabled=true;const progress=document.getElementById('offline-progress');if(progress){progress.hidden=false;progress.value=0;}status.textContent='Downloading app, model and six guides...';try{const reg=await navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'});await activated(reg);if(!await message(reg.active,'STATUS')){if(!await message(reg.active,'REPAIR',90000))throw new Error('Incomplete download');}await refresh();if(progress)progress.value=100;navigator.storage?.persist?.().catch(()=>{});}catch(error){status.textContent=error.name==='QuotaExceededError'?'Not enough browser storage. Free some space and retry.':`Offline download failed: ${error.message||'browser storage unavailable'}. Keep this page open and retry.`;}finally{button.disabled=false;}};
navigator.serviceWorker?.addEventListener('controllerchange',()=>{if(!button.disabled)refresh();});window.addEventListener('online',refresh);window.addEventListener('offline',refresh);refresh();

navigator.serviceWorker?.addEventListener('message',event=>{if(event.data?.type!=='OFFLINE_PROGRESS'||!button.disabled)return;const {done,total}=event.data;status.textContent=`Saving offline files: ${done} of ${total}`;const progress=document.getElementById('offline-progress');if(progress){progress.hidden=false;progress.value=Math.round(done/total*100);}});
